// collectRawMessages - shared logic to convert raw CLN entries into RawMessages
// while computing the pagination time window. timeFromEntry extracts the
// timestamp for a single (still encoded) entry.
func (l *ClnSocketLightningAPI) collectRawMessages(entries []json.RawMessage, timeFromEntry func(json.RawMessage) (time.Time, error)) ([]RawMessage, *ResponseRawPagination, error) {
	respPagination := &ResponseRawPagination{UseTimestamp: true}

	ret := make([]RawMessage, 0, len(entries))

	minTime := time.Unix(1<<63-1, 0)
	maxTime := time.Unix(0, 0)

	for _, one := range entries {
		t, err := timeFromEntry(one)
		if err != nil {
			return nil, respPagination, err
		}

		if t.Before(minTime) {
			minTime = t
		}
		if t.After(maxTime) {
			maxTime = t
		}

		ret = append(ret, RawMessage{
			Implementation: l.Name,
			Timestamp:      t,
			Message:        one,
		})
	}

	respPagination.FirstTime = minTime
	respPagination.LastTime = maxTime

	return ret, respPagination, nil
}

// GetInvoicesRaw - API call
func (l *ClnSocketLightningAPI) GetInvoicesRaw(ctx context.Context, pendingOnly bool, pagination RawPagination) ([]RawMessage, *ResponseRawPagination, error) {
	var reply ClnRawInvoices

	err := l.CallWithTimeout(LISTINVOICES, []interface{}{}, &reply)
	if err != nil {
		return nil, &ResponseRawPagination{UseTimestamp: true}, err
	}

	return l.collectRawMessages(reply.Entries, func(one json.RawMessage) (time.Time, error) {
		var gettime ClnRawInvoiceTime
		if err := json.Unmarshal(one, &gettime); err != nil {
			return time.Time{}, err
		}
		return time.Unix(int64(gettime.Time), 0), nil
	})
}

// GetPaymentsRaw - API call
func (l *ClnSocketLightningAPI) GetPaymentsRaw(ctx context.Context, includeIncomplete bool, pagination RawPagination) ([]RawMessage, *ResponseRawPagination, error) {
	var reply ClnRawPayments

	err := l.CallWithTimeout(LISTPAYMENTS, []interface{}{}, &reply)
	if err != nil {
		return nil, &ResponseRawPagination{UseTimestamp: true}, err
	}

	return l.collectRawMessages(reply.Entries, func(one json.RawMessage) (time.Time, error) {
		var gettime ClnRawPayTime
		if err := json.Unmarshal(one, &gettime); err != nil {
			return time.Time{}, err
		}
		return time.Unix(int64(gettime.Time), 0), nil
	})
}

// GetForwardsRaw - API call
func (l *ClnSocketLightningAPI) GetForwardsRaw(ctx context.Context, pagination RawPagination) ([]RawMessage, *ResponseRawPagination, error) {
	var reply ClnRawForwardEntries

	err := l.CallWithTimeout(LISTFORWARDS, []interface{}{}, &reply)
	if err != nil {
		return nil, &ResponseRawPagination{UseTimestamp: true}, err
	}

	return l.collectRawMessages(reply.Entries, func(one json.RawMessage) (time.Time, error) {
		var gettime ClnRawForwardsTime
		if err := json.Unmarshal(one, &gettime); err != nil {
			return time.Time{}, err
		}
		return time.Unix(int64(gettime.Time), 0), nil
	})
}

